import type { TabBarPanelProps } from "../tab-bar.types";

import { forwardRef } from "react";
import * as RadixTabs from "@radix-ui/react-tabs";
import { clsx } from "clsx";

import { TabBarClasses } from "../tab-bar.styles";

export const TabBarPanel = forwardRef<
  HTMLDivElement,
  TabBarPanelProps & RadixTabs.TabsContentProps
>(({ className, value = "", children, ...props }, ref) => (
  <RadixTabs.Content
    ref={ref}
    className={clsx(TabBarClasses.panel, className)}
    value={value}
    {...props}
  >
    {children}
  </RadixTabs.Content>
));

TabBarPanel.displayName = "TabBar.Panel";
